    "instruction": "請選擇 4 項錯誤的答案。",
    "stem": "你正在帶領一名培訓中的稽核員進行知識複習。\n\n你是一位經驗豐富的 ISMS 稽核組長，培訓中的稽核員詢問不符合性的分級。請選擇下列四項「不適當」的陳述。",
