    "instruction": "請選擇 3 項正確的答案。",
    "stem": "你正在規劃一次第三方驗證稽核，並向稽核小組說明準備方式。\n\n第二階段稽核的啟始會議上，受稽核方的執行長邀請稽核團隊觀看 45 分鐘的新公司影片。請選擇三項較適當的回應。",
